49 | // IsPublicMethod checks if a procedure path is public (no authentication required).
50 | // Returns true for public methods, false for protected methods.
51 | func IsPublicMethod(procedure string) bool {
52 | 	_, ok := PublicMethods[procedure]
53 | 	return ok
54 | }
